219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
222	        Owner owner = this.clinicService.findOwnerById(ownerId);
223	        if (owner != null) {
224	            Pet pet = owner.getPet(petId);
225	            if (pet != null) {
226	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
227	            }
228	        }
229	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
230	    }
231	
232	    /**
233	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
234	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
235	     *
236	     * @param fields the submitted owner fields
237	     * @throws RequiredFieldsMissingException if any of firstName, lastName, address, city or telephone is
238	     *                                        {@code null} or blank
239	     */
240	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
241	        List<String> missing = new ArrayList<>();
242	        if (isBlank(fields.getFirstName())) {
243	            missing.add("firstName");
244	        }
245	        if (isBlank(fields.getLastName())) {
246	            missing.add("lastName");
247	        }
248	        if (isBlank(fields.getAddress())) {
249	            missing.add("address");
250	        }
251	        if (isBlank(fields.getCity())) {
252	            missing.add("city");
253	        }
254	        if (isBlank(fields.getTelephone())) {
255	            missing.add("telephone");
256	        }
257	        if (!missing.isEmpty()) {
258	            throw new RequiredFieldsMissingException(missing);
259	        }
260	    }
261	
262	    private boolean isBlank(String value) {
263	        return value == null || value.isBlank();
264	    }
265	
266	    /**
267	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
268	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
269	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
270	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
271	     *
272	     * @param telephone the raw telephone value from the request
273	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
274	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
275	     */
276	    private String normalizeTelephone(String telephone) {
277	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
278	        String digits;
279	        if (cleaned.startsWith("+")) {
280	            digits = cleaned.substring(1);
281	        } else {
282	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
283	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
284	            digits = "61" + national;
285	        }
286	        if (!digits.matches("[0-9]{8,15}")) {
287	            throw new InvalidTelephoneException(cleaned);
288	        }
289	        return "+" + digits;
290	    }
291	
292	    /**
293	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
294	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
295	     * lower-cased.
296	     *
297	     * @param email the raw email value from the request, or {@code null} if omitted
298	     * @return the lower-cased email, or {@code null} if none was supplied
299	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
300	     */
301	    private String normalizeEmail(String email) {
302	        if (email == null) {
303	            return null;
304	        }
305	        String trimmed = email.strip();
306	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
307	            throw new InvalidEmailException(email);
308	        }
309	        return trimmed.toLowerCase(Locale.ROOT);
310	    }
311	
312	    /**
313	     * Rejects a create request whose normalized telephone is already used by another owner. Owners store
314	     * their telephone in normalized E.164 form, so an exact string comparison of E.164 values is sufficient.
315	     *
316	     * @param telephone the normalized (E.164) telephone of the owner being created
317	     * @throws DuplicateTelephoneException if any existing owner already uses the telephone
318	     */
319	    /**
320	     * Builds the customer code assigned to a newly created owner, formatted {@code '<LAST3>-<NNNN>'} where
321	     * {@code LAST3} is the upper-cased first three letters of the owner's last name and {@code NNNN} is a
322	     * global 4-digit zero-padded sequence equal to one more than the current number of owners (e.g.
323	     * {@code 'SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes it.
324	     *
325	     * @param lastName the owner's last name
326	     * @return the assigned customer code
327	     */
328	    private String generateCustomerCode(String lastName) {
329	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
330	        int sequence = this.clinicService.findAllOwners().size() + 1;
331	        return String.format("%s-%04d", last3, sequence);
332	    }
333	
334	    private void rejectDuplicateTelephone(String telephone) {
335	        boolean taken = this.clinicService.findAllOwners().stream()
336	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
337	        if (taken) {
338	            throw new DuplicateTelephoneException(telephone);
339	        }
340	    }
341	
342	    /**
343	     * Rejects a create request whose owner shares both last name and address with an existing owner.
344	     * Last name and address are compared case-insensitively with runs of whitespace collapsed to a
345	     * single space and leading/trailing whitespace removed, so cosmetic differences (extra spaces,
346	     * differing case) still count as the same household.
347	     *
348	     * @param lastName the last name of the owner being created
349	     * @param address the address of the owner being created
350	     * @throws DuplicateHouseholdException if an existing owner has the same last name and address
351	     */
352	    private void rejectDuplicateHousehold(String lastName, String address) {
353	        String normalizedLastName = normalizeForComparison(lastName);
354	        String normalizedAddress = normalizeForComparison(address);
355	        boolean taken = this.clinicService.findAllOwners().stream()
356	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
357	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
358	        if (taken) {
359	            throw new DuplicateHouseholdException(lastName, address);
360	        }
361	    }
362	
363	    /**
364	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
365	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
366	     * lower-cased.
367	     *
368	     * @param value the raw value to normalize (may be {@code null})
369	     * @return the normalized value, or an empty string when {@code value} is {@code null}
370	     */
371	    private String normalizeForComparison(String value) {
372	        if (value == null) {
373	            return "";
374	        }
375	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
376	    }
377	}
