240	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
241	        List<String> missing = new ArrayList<>();
242	        if (isBlank(fields.getFirstName())) { missing.add("firstName"); }
245	        if (isBlank(fields.getLastName()))  { missing.add("lastName"); }
248	        if (isBlank(fields.getAddress()))   { missing.add("address"); }
251	        if (isBlank(fields.getCity()))      { missing.add("city"); }
