306	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) { throw new InvalidEmailException(email); }
309	        return trimmed.toLowerCase(Locale.ROOT);
310	    }

328	    private String generateCustomerCode(String lastName) {
329	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
330	        int sequence = this.clinicService.findAllOwners().size() + 1;
331	        return String.format("%s-%04d", last3, sequence);
332	    }

334	    private void rejectDuplicateTelephone(String telephone) {
335	        boolean taken = this.clinicService.findAllOwners().stream()
336	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
337	        if (taken) { throw new DuplicateTelephoneException(telephone); }
340	    }

352	    private void rejectDuplicateHousehold(String lastName, String address) {
353	        String normalizedLastName = normalizeForComparison(lastName);
354	        String normalizedAddress = normalizeForComparison(address);
355	        boolean taken = this.clinicService.findAllOwners().stream()
356	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
357	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())));
358	        if (taken) { throw new DuplicateHouseholdException(lastName, address); }
361	    }

371	    private String normalizeForComparison(String value) {
372	        if (value == null) { return ""; }
375	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
376	    }
```

